definition.script:
pipeline {
  agent any

  tools {
    nodejs 'node25'
  }

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15', artifactNumToKeepStr: '5'))
    timeout(time: 240, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  environment {
    NEXUS_REGISTRY = 'localhost:5001'
    // BuildKit in Jenkins resolves the app parents from the registry rather
    // than the local Docker image store, so app Dockerfiles must point at the
    // pushed Nexus namespace instead of the bare local "metabuilder" name.
    BASE_REGISTRY = 'localhost:5001/johndoe6345789/metabuilder'
    // pkgrepo package cache (npm/conan pull-through) on the host NVMe.
    PKGREPO_REGISTRY = 'http://172.17.0.1:5002'
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/metabuilder.git'
      }
    }

    stage('Docker Preflight') {
      options { timeout(time: 10, unit: 'MINUTES') }
      steps {
        sh '''
          docker version
          docker compose version
          curl -fsS -I http://localhost:5001/v2/ || true
        '''
      }
    }

    // Pull the last-good base images from Nexus and retag them to the local
    // names the app Dockerfiles expect (FROM metabuilder/base-*:latest). This
    // is what makes the apps job independent of whether the base-images job
    // rebuilt anything this cycle: a missing/failed base no longer cascades
    // into "pull access denied for metabuilder/base-apt" (build #9). Pull is
    // best-effort per image; the per-app catchError below tolerates a base
    // that has never been published yet.
    stage('Hydrate Base Images From Nexus') {
      options { timeout(time: 45, unit: 'MINUTES') }
      steps {
        sh '''
          python3 - <<'PY'
import json
import os
import subprocess
import sys

with open("deployment/cli/commands.json") as f:
    defs = json.load(f)["definitions"]["nexus_images"]

registry = os.environ.get("NEXUS_REGISTRY", "localhost:5001")
slug = "johndoe6345789/metabuilder"
images = defs["base"] + defs.get("heavy", [])

hydrated = 0
missing = []
for image in images:
    local = image["local"]
    name = image["name"]
    src = f"{registry}/{slug}/{name}:latest"
    if subprocess.run(["docker", "pull", src]).returncode != 0:
        missing.append(src)
        continue
    subprocess.check_call(["docker", "tag", src, local])
    subprocess.run(["docker", "rmi", "-f", src], check=False)
    hydrated += 1
    print(f"Hydrated {local} from {src}")

print(f"Hydrated {hydrated} base images from {registry}/{slug}")
if missing:
    print("Base images not yet in Nexus (dependent apps will be skipped):", file=sys.stderr)
    for src in missing:
        print(f"  - {src}", file=sys.stderr)
PY
        '''
      }
    }

    stage('Install') {
      options { timeout(time: 25, unit: 'MINUTES') }
      steps {
        sh '''
          # Route ALL npm through the pkgrepo cache (fetch from npmjs -> store in
          # S3 -> serve) at the docker host-gateway URL (172.17.0.1), which is
          # reachable from the agent AND the bridge-network app docker builds
          # that COPY this .npmrc.
          npm config set registry "$PKGREPO_REGISTRY/npm" --location=project
          npm config set @esbuild-kit:registry https://registry.npmjs.org/ --location=project
          npm install --no-audit --no-fund
        '''
      }
    }

    stage('Validate') {
      options { timeout(time: 25, unit: 'MINUTES') }
      steps {
        sh '''
          npm run lint --if-present
          npm run typecheck --if-present
          npm test --if-present
          npm run build --if-present
        '''
      }
    }

    // One stage per app image from the same manifest (commands.json). Kept
    // SEQUENTIAL on purpose: this host is disk-constrained and concurrent
    // image builds would blow peak disk. Each app is fault-tolerant: a failure
    // (typically a base that was not published to Nexus) marks the build
    // UNSTABLE and the stage skipped, instead of aborting the whole run, so
    // every buildable image still reaches the push stage.
    //
    // CHANGE-AWARE: only rebuild apps whose source changed since the last
    // SUCCESSFUL build; rebuild EVERYTHING when shared code changes or the diff
    // can't be trusted. This keeps full-fleet builds (all ~16 apps, >2h) for
    // the rare shared-code change while making the common single-app change
    // fast, so runs stop hitting the job timeout. Safe-by-default: any doubt =>
    // rebuild. Built apps still use --force (the deploy job hydrates stale
    // metabuilder-deploy-<svc> tags onto these shared agents, which would
    // otherwise make the skip logic reuse old code); skipped apps keep their
    // existing registry :latest, which the deploy job re-pulls unchanged.
    stage('Build App Images (per-image)') {
      options { timeout(time: 210, unit: 'MINUTES') }
      steps {
        script {
          def defs = readJSON file: 'deployment/cli/commands.json'
          def apps = defs.definitions.nexus_images.apps
          if (defs.definitions.nexus_images.heavy_apps) {
            apps += defs.definitions.nexus_images.heavy_apps
          }

          def shared = ['redux/','components/','hooks/','types/','interfaces/',
                        'translations/','workflow/','scss/','config/','packages/',
                        'schemas/','deployment/','package.json',
                        'package-lock.json','.npmrc']
          def appPaths = [
            'pastebin': ['frontends/pastebin/'],
            'pastebin-backend': ['frontends/pastebin/backend/'],
            'frontend-app': ['frontends/nextjs/'],
            'workflowui': ['frontends/workflowui/'],
            'postgres-dashboard': ['frontends/postgres/'],
            'codegen': ['frontends/codegen/'],
            'emailclient-app': ['frontends/emailclient/'],
            'email-service': ['frontends/emailclient/'],
            'exploded-diagrams': ['frontends/exploded-diagrams/'],
            'storybook': ['storybook/'],
            'dbal': ['dbal/'],
            'dbal-init': ['dbal/'],
            'smtp-relay': ['services/smtprelay/'],
            'media-daemon': ['services/media_daemon/'],
            'nginx': ['deployment/config/nginx/'],
            'nginx-stream': ['deployment/config/nginx/']
          ]

          // Reference commit = the SHA recorded by the most recent prior build
          // that completed (SUCCESS/UNSTABLE). Stored in the build description so
          // it survives the ephemeral, shared agents (env.GIT_PREVIOUS_SUCCESSFUL_COMMIT
          // is unreliable with the scripted git step). Record HEAD now so the
          // next run can diff against it; worst case (no prior SHA / bad diff)
          // falls through to building ALL apps, which is always safe.
          def headSha = sh(script: 'git rev-parse HEAD', returnStdout: true).trim()
          currentBuild.description = headSha

          def prev = null
          def pb = currentBuild.previousBuild
          while (pb != null) {
            def r = pb.result
            def d = pb.description
            if ((r == 'SUCCESS' || r == 'UNSTABLE') && d != null && d ==~ /[0-9a-f]{40}/) {
              prev = d.trim()
              break
            }
            pb = pb.previousBuild
          }

          def buildAll = false
          def changed = []
          if (!prev) {
            echo 'No prior built commit recorded -> building ALL apps.'
            buildAll = true
          } else {
            def known = sh(script: "git cat-file -e ${prev} 2>/dev/null", returnStatus: true)
            if (known != 0) {
              echo "Prior commit ${prev} not in history -> building ALL apps."
              buildAll = true
            } else {
              def out = sh(script: "git diff --name-only ${prev} HEAD", returnStdout: true).trim()
              changed = out ? out.readLines() : []
              echo "Changed files since ${prev}: ${changed.size()}"
              if (changed.any { f -> shared.any { p -> f.startsWith(p) } }) {
                echo 'Shared/CI code changed -> building ALL apps.'
                buildAll = true
              }
            }
          }

          for (entry in apps) {
            def svc = entry.name
            def doBuild = buildAll
            if (!doBuild) {
              def prefixes = appPaths[svc]
              if (prefixes == null) {
                doBuild = true
              } else {
                doBuild = changed.any { f -> prefixes.any { p -> f.startsWith(p) } }
              }
            }
            if (!doBuild) {
              echo "Skipping ${svc} -- no source changes since last successful build"
              continue
            }
            stage("app: ${svc}") {
              catchError(message: "app ${svc} build failed (likely a base image not yet published to Nexus)", buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
                sh """
                  set -e
                  cd deployment
                  python3 deployment.py build apps --force ${svc}
                  docker builder prune -f --filter until=24h || true
                """
              }
            }
          }
        }
      }
    }

    stage('Push App Images To Nexus') {
      options { timeout(time: 45, unit: 'MINUTES') }
      steps {
        sh '''
          tag="$(git rev-parse --short HEAD)"
          slug="johndoe6345789/metabuilder"

          python3 - <<'PY'
import json
import os
import subprocess
import sys

with open("deployment/cli/commands.json") as f:
    defs = json.load(f)["definitions"]["nexus_images"]

registry = os.environ.get("NEXUS_REGISTRY", "localhost:5001")
tag = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], text=True).strip()
slug = "johndoe6345789/metabuilder"
# Apps job publishes ONLY app images; base images are owned by the base job.
images = defs["apps"] + defs.get("heavy_apps", [])

pushed = 0
missing = []
for image in images:
    local = image["local"]
    name = image["name"]
    if subprocess.run(["docker", "image", "inspect", local], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode != 0:
        missing.append(local)
        continue

    targets = [
        f"{registry}/{slug}/{name}:{tag}",
        f"{registry}/{slug}/{name}:latest",
    ]
    for target in targets:
        subprocess.check_call(["docker", "tag", local, target])
        subprocess.check_call(["docker", "push", target])
        subprocess.run(["docker", "rmi", "-f", target], check=False)
        pushed += 1

    subprocess.run(["docker", "rmi", "-f", local], check=False)
    subprocess.run(["docker", "builder", "prune", "-af", "--filter", "until=24h"], check=False)

print(f"Pushed {pushed} app image tags to {registry}/{slug}")
if missing:
    print("Skipped app images that were not built:", file=sys.stderr)
    for local in missing:
        print(f"  - {local}", file=sys.stderr)
PY
        '''
      }
    }
  }

  post {
    always {
      cleanWs()
    }
  }
}
